Inductive ExceptionKind :=
  | StackUnderflow
  | StackOverflow
  | OutOfGas
  | InvalidOpcode
  | InvalidJump
  | StaticViolation
  | CallDepthExceeded
  | InsufficientBalance
  | WriteProtection
  | InitCodeTooLarge
  | NonceOverflow
  | AddressCollision.
Definition num_of_ExceptionKind (arg_ : ExceptionKind) : Z :=
   match arg_ with
   | StackUnderflow => 0
   | StackOverflow => 1
   | OutOfGas => 2
   | InvalidOpcode => 3
   | InvalidJump => 4
   | StaticViolation => 5
   | CallDepthExceeded => 6
   | InsufficientBalance => 7
   | WriteProtection => 8
   | InitCodeTooLarge => 9
   | NonceOverflow => 10
   | AddressCollision => 11
   end.

Definition ExceptionKind_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 11)*) : ExceptionKind :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then StackUnderflow
   else if Z.eqb (l__0) (1) then StackOverflow
   else if Z.eqb (l__0) (2) then OutOfGas
   else if Z.eqb (l__0) (3) then InvalidOpcode
   else if Z.eqb (l__0) (4) then InvalidJump
   else if Z.eqb (l__0) (5) then StaticViolation
   else if Z.eqb (l__0) (6) then CallDepthExceeded
   else if Z.eqb (l__0) (7) then InsufficientBalance
   else if Z.eqb (l__0) (8) then WriteProtection
   else if Z.eqb (l__0) (9) then InitCodeTooLarge
   else if Z.eqb (l__0) (10) then NonceOverflow
   else AddressCollision.

Lemma ExceptionKind_num_of_roundtrip (x : ExceptionKind) : ExceptionKind_of_num (num_of_ExceptionKind x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_ExceptionKind_injective (x y : ExceptionKind) : num_of_ExceptionKind x = num_of_ExceptionKind y -> x = y.
  intro.
  rewrite <- (ExceptionKind_num_of_roundtrip x).
  rewrite <- (ExceptionKind_num_of_roundtrip y).
  congruence.
Qed.
Definition ExceptionKind_eq_dec (x y : ExceptionKind) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_ExceptionKind x) (num_of_ExceptionKind y) with
  | left e => left (num_of_ExceptionKind_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition ExceptionKind_beq (x y : ExceptionKind) : bool :=
  Z.eqb (num_of_ExceptionKind x) (num_of_ExceptionKind y).
Lemma ExceptionKind_beq_iff x y : ExceptionKind_beq x y = true <-> x = y.
  unfold ExceptionKind_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_ExceptionKind_injective | congruence].
Qed.
Lemma ExceptionKind_beq_refl x : ExceptionKind_beq x x = true.
apply ExceptionKind_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_ExceptionKind : EqDecision ExceptionKind := ExceptionKind_eq_dec.
#[export]
Instance Countable_ExceptionKind : Countable ExceptionKind.
refine {|
  encode x := encode (num_of_ExceptionKind x);
  decode x := z ← decode x; mret (ExceptionKind_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite ExceptionKind_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_ExceptionKind : Inhabited ExceptionKind := { inhabitant := StackUnderflow }.


