refine {|
  encode x := encode (StorageKey_addr x, StorageKey_slot x);
  decode x := '(x0, x1) ← decode x;
              mret (Build_StorageKey x0 x1)
|}.
abstract (
  intros [x0 x1];
  rewrite decode_encode;
  reflexivity).
Defined.

Notation "{[ r 'with' 'StorageKey_addr' := e ]}" :=
  match r with Build_StorageKey _ (_ as f1) => Build_StorageKey e f1 end (at level 1).
Notation "{[ r 'with' 'StorageKey_slot' := e ]}" :=
  match r with Build_StorageKey (_ as f0) _ => Build_StorageKey f0 e end (at level 1).
#[export]
Instance dummy_StorageKey : Inhabited (StorageKey) := {
  inhabitant := {| StorageKey_addr := inhabitant; StorageKey_slot := inhabitant
|} }.


