Inductive TxType := LegacyTx | AccessListTx | FeeMarketTx | BlobTx | SetCodeTx.
Definition num_of_TxType (arg_ : TxType) : Z :=
   match arg_ with
   | LegacyTx => 0
   | AccessListTx => 1
   | FeeMarketTx => 2
   | BlobTx => 3
   | SetCodeTx => 4
   end.

Definition TxType_of_num (arg_ : Z) (*(0 <=? arg_) && (arg_ <=? 4)*) : TxType :=
   let l__0 := arg_ in
   if Z.eqb (l__0) (0) then LegacyTx
   else if Z.eqb (l__0) (1) then AccessListTx
   else if Z.eqb (l__0) (2) then FeeMarketTx
   else if Z.eqb (l__0) (3) then BlobTx
   else SetCodeTx.

Lemma TxType_num_of_roundtrip (x : TxType) : TxType_of_num (num_of_TxType x) = x.
  destruct x; reflexivity.
Qed.
Lemma num_of_TxType_injective (x y : TxType) : num_of_TxType x = num_of_TxType y -> x = y.
  intro.
  rewrite <- (TxType_num_of_roundtrip x).
  rewrite <- (TxType_num_of_roundtrip y).
  congruence.
Qed.
Definition TxType_eq_dec (x y : TxType) : {x = y} + {x <> y}.
  refine (match Z.eq_dec (num_of_TxType x) (num_of_TxType y) with
  | left e => left (num_of_TxType_injective x y e)
  | right ne => right _
  end).
  congruence.
Defined.
Definition TxType_beq (x y : TxType) : bool :=
  Z.eqb (num_of_TxType x) (num_of_TxType y).
Lemma TxType_beq_iff x y : TxType_beq x y = true <-> x = y.
  unfold TxType_beq.
  rewrite Z.eqb_eq.
  split; [apply num_of_TxType_injective | congruence].
Qed.
Lemma TxType_beq_refl x : TxType_beq x x = true.
apply TxType_beq_iff; reflexivity.
Qed.
#[export]
Instance Decidable_eq_TxType : EqDecision TxType := TxType_eq_dec.
#[export]
Instance Countable_TxType : Countable TxType.
refine {|
  encode x := encode (num_of_TxType x);
  decode x := z ← decode x; mret (TxType_of_num z);
|}.
abstract (
  intro s; rewrite decode_encode;
  simpl;
  rewrite TxType_num_of_roundtrip;
  reflexivity).
Defined.
#[export]
Instance dummy_TxType : Inhabited TxType := { inhabitant := LegacyTx }.


