| CODECOPY : unit -> ast
| GASPRICE : unit -> ast
| EXTCODESIZE : unit -> ast
| EXTCODECOPY : unit -> ast
| RETURNDATASIZE : unit -> ast
| RETURNDATACOPY : unit -> ast
| EXTCODEHASH : unit -> ast
| BLOCKHASH : unit -> ast
| COINBASE : unit -> ast
| TIMESTAMP : unit -> ast
| NUMBER : unit -> ast
