Arguments ast : clear implicits.

Definition sail_ast_encode (x : ast) := match x with
  | STOP x' => encode (0, encode x')
  | ADD x' => encode (1, encode x')
  | MUL x' => encode (2, encode x')
  | SUB x' => encode (3, encode x')
  | DIV x' => encode (4, encode x')
  | SDIV x' => encode (5, encode x')
  | MOD x' => encode (6, encode x')
  | SMOD x' => encode (7, encode x')
  | ADDMOD x' => encode (8, encode x')
  | MULMOD x' => encode (9, encode x')
  | EXP x' => encode (10, encode x')
  | SIGNEXTEND x' => encode (11, encode x')
  | LT' x' => encode (12, encode x')
  | GT' x' => encode (13, encode x')
  | SLT x' => encode (14, encode x')
  | SGT x' => encode (15, encode x')
  | EQ' x' => encode (16, encode x')
  | ISZERO x' => encode (17, encode x')
  | AND x' => encode (18, encode x')
  | OR x' => encode (19, encode x')
  | XOR x' => encode (20, encode x')
  | NOT x' => encode (21, encode x')
  | BYTE x' => encode (22, encode x')
  | SHL x' => encode (23, encode x')
  | SHR x' => encode (24, encode x')
  | SAR x' => encode (25, encode x')
  | CLZ x' => encode (26, encode x')
  | KECCAK256 x' => encode (27, encode x')
  | ADDRESS x' => encode (28, encode x')
  | BALANCE x' => encode (29, encode x')
  | ORIGIN x' => encode (30, encode x')
  | CALLER x' => encode (31, encode x')
  | CALLVALUE x' => encode (32, encode x')
  | CALLDATALOAD x' => encode (33, encode x')
  | CALLDATASIZE x' => encode (34, encode x')
  | CALLDATACOPY x' => encode (35, encode x')
  | CODESIZE x' => encode (36, encode x')
  | CODECOPY x' => encode (37, encode x')
  | GASPRICE x' => encode (38, encode x')
  | EXTCODESIZE x' => encode (39, encode x')
  | EXTCODECOPY x' => encode (40, encode x')
  | RETURNDATASIZE x' => encode (41, encode x')
  | RETURNDATACOPY x' => encode (42, encode x')
  | EXTCODEHASH x' => encode (43, encode x')
  | BLOCKHASH x' => encode (44, encode x')
  | COINBASE x' => encode (45, encode x')
  | TIMESTAMP x' => encode (46, encode x')
  | NUMBER x' => encode (47, encode x')
  | PREVRANDAO x' => encode (48, encode x')
  | GASLIMIT x' => encode (49, encode x')
  | CHAINID x' => encode (50, encode x')
  | SELFBALANCE x' => encode (51, encode x')
  | BASEFEE x' => encode (52, encode x')
  | BLOBHASH x' => encode (53, encode x')
  | BLOBBASEFEE x' => encode (54, encode x')
  | SLOTNUM x' => encode (55, encode x')
  | POP x' => encode (56, encode x')
  | MLOAD x' => encode (57, encode x')
  | MSTORE x' => encode (58, encode x')
  | MSTORE8 x' => encode (59, encode x')
  | SLOAD x' => encode (60, encode x')
  | SSTORE x' => encode (61, encode x')
  | JUMP x' => encode (62, encode x')
  | JUMPI x' => encode (63, encode x')
  | PC x' => encode (64, encode x')
  | MSIZE x' => encode (65, encode x')
  | GAS x' => encode (66, encode x')
  | JUMPDEST x' => encode (67, encode x')
  | TLOAD x' => encode (68, encode x')
  | TSTORE x' => encode (69, encode x')
  | MCOPY x' => encode (70, encode x')
  | PUSH x' => encode (71, encode x')
  | DUP x' => encode (72, encode x')
  | SWAP x' => encode (73, encode x')
  | LOG x' => encode (74, encode x')
  | DUPN x' => encode (75, encode x')
  | SWAPN x' => encode (76, encode x')
  | EXCHANGE x' => encode (77, encode x')
  | CREATE x' => encode (78, encode x')
  | CALL x' => encode (79, encode x')
  | CALLCODE x' => encode (80, encode x')
  | RETURN x' => encode (81, encode x')
  | DELEGATECALL x' => encode (82, encode x')
  | CREATE2 x' => encode (83, encode x')
  | STATICCALL x' => encode (84, encode x')
  | REVERT x' => encode (85, encode x')
  | INVALID x' => encode (86, encode x')
  | SELFDESTRUCT x' => encode (87, encode x') end.
Definition sail_ast_decode x : option ast := match decode x with
  | Some (0, x') => STOP <$> decode x'
  | Some (1, x') => ADD <$> decode x'
  | Some (2, x') => MUL <$> decode x'
  | Some (3, x') => SUB <$> decode x'
  | Some (4, x') => DIV <$> decode x'
  | Some (5, x') => SDIV <$> decode x'
  | Some (6, x') => MOD <$> decode x'
  | Some (7, x') => SMOD <$> decode x'
  | Some (8, x') => ADDMOD <$> decode x'
  | Some (9, x') => MULMOD <$> decode x'
  | Some (10, x') => EXP <$> decode x'
  | Some (11, x') => SIGNEXTEND <$> decode x'
  | Some (12, x') => LT' <$> decode x'
  | Some (13, x') => GT' <$> decode x'
  | Some (14, x') => SLT <$> decode x'
  | Some (15, x') => SGT <$> decode x'
  | Some (16, x') => EQ' <$> decode x'
  | Some (17, x') => ISZERO <$> decode x'
  | Some (18, x') => AND <$> decode x'
  | Some (19, x') => OR <$> decode x'
  | Some (20, x') => XOR <$> decode x'
  | Some (21, x') => NOT <$> decode x'
  | Some (22, x') => BYTE <$> decode x'
  | Some (23, x') => SHL <$> decode x'
  | Some (24, x') => SHR <$> decode x'
  | Some (25, x') => SAR <$> decode x'
  | Some (26, x') => CLZ <$> decode x'
  | Some (27, x') => KECCAK256 <$> decode x'
  | Some (28, x') => ADDRESS <$> decode x'
  | Some (29, x') => BALANCE <$> decode x'
  | Some (30, x') => ORIGIN <$> decode x'
  | Some (31, x') => CALLER <$> decode x'
  | Some (32, x') => CALLVALUE <$> decode x'
  | Some (33, x') => CALLDATALOAD <$> decode x'
  | Some (34, x') => CALLDATASIZE <$> decode x'
  | Some (35, x') => CALLDATACOPY <$> decode x'
  | Some (36, x') => CODESIZE <$> decode x'
  | Some (37, x') => CODECOPY <$> decode x'
  | Some (38, x') => GASPRICE <$> decode x'
  | Some (39, x') => EXTCODESIZE <$> decode x'
  | Some (40, x') => EXTCODECOPY <$> decode x'
  | Some (41, x') => RETURNDATASIZE <$> decode x'
  | Some (42, x') => RETURNDATACOPY <$> decode x'
  | Some (43, x') => EXTCODEHASH <$> decode x'
  | Some (44, x') => BLOCKHASH <$> decode x'
  | Some (45, x') => COINBASE <$> decode x'
  | Some (46, x') => TIMESTAMP <$> decode x'
  | Some (47, x') => NUMBER <$> decode x'
  | Some (48, x') => PREVRANDAO <$> decode x'
  | Some (49, x') => GASLIMIT <$> decode x'
  | Some (50, x') => CHAINID <$> decode x'
  | Some (51, x') => SELFBALANCE <$> decode x'
  | Some (52, x') => BASEFEE <$> decode x'
  | Some (53, x') => BLOBHASH <$> decode x'
  | Some (54, x') => BLOBBASEFEE <$> decode x'
  | Some (55, x') => SLOTNUM <$> decode x'
  | Some (56, x') => POP <$> decode x'
  | Some (57, x') => MLOAD <$> decode x'
  | Some (58, x') => MSTORE <$> decode x'
  | Some (59, x') => MSTORE8 <$> decode x'
  | Some (60, x') => SLOAD <$> decode x'
  | Some (61, x') => SSTORE <$> decode x'
  | Some (62, x') => JUMP <$> decode x'
  | Some (63, x') => JUMPI <$> decode x'
  | Some (64, x') => PC <$> decode x'
  | Some (65, x') => MSIZE <$> decode x'
  | Some (66, x') => GAS <$> decode x'
  | Some (67, x') => JUMPDEST <$> decode x'
  | Some (68, x') => TLOAD <$> decode x'
  | Some (69, x') => TSTORE <$> decode x'
  | Some (70, x') => MCOPY <$> decode x'
  | Some (71, x') => PUSH <$> decode x'
  | Some (72, x') => DUP <$> decode x'
  | Some (73, x') => SWAP <$> decode x'
  | Some (74, x') => LOG <$> decode x'
  | Some (75, x') => DUPN <$> decode x'
  | Some (76, x') => SWAPN <$> decode x'
  | Some (77, x') => EXCHANGE <$> decode x'
  | Some (78, x') => CREATE <$> decode x'
  | Some (79, x') => CALL <$> decode x'
  | Some (80, x') => CALLCODE <$> decode x'
  | Some (81, x') => RETURN <$> decode x'
  | Some (82, x') => DELEGATECALL <$> decode x'
  | Some (83, x') => CREATE2 <$> decode x'
  | Some (84, x') => STATICCALL <$> decode x'
  | Some (85, x') => REVERT <$> decode x'
  | Some (86, x') => INVALID <$> decode x'
  | Some (87, x') => SELFDESTRUCT <$> decode x'
  | _ => None end.
Lemma sail_ast_decode_encode : forall (x : ast), sail_ast_decode (sail_ast_encode x)  = Some x.
Proof.
  unfold sail_ast_decode, sail_ast_encode;
  intros [x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x|x]; rewrite !decode_encode; reflexivity.
Qed.

#[export]
Instance Decidable_eq_ast : EqDecision ast := decode_encode_eq_dec sail_ast_encode sail_ast_decode
  sail_ast_decode_encode .

#[export]
Instance Countable_ast : Countable ast := {|
  encode := sail_ast_encode;
  decode := sail_ast_decode;
  decode_encode := sail_ast_decode_encode
|}.
#[export]
Instance dummy_ast : Inhabited (ast) := { inhabitant := STOP inhabitant }.

Record IntrinsicGasCost := {
  IntrinsicGasCost_execution : gas_cost;
  IntrinsicGasCost_state : gas_cost;
  IntrinsicGasCost_calldata_floor : gas_cost;
}.
Arguments IntrinsicGasCost : clear implicits.
#[export]
Instance Decidable_eq_IntrinsicGasCost : EqDecision IntrinsicGasCost.
   intros [x0 x1 x2].
   intros [y0 y1 y2].
  cmp_record_field x0 y0.
  cmp_record_field x1 y1.
  cmp_record_field x2 y2.
left; subst; reflexivity.
Defined.
#[export]
Instance Countable_IntrinsicGasCost : Countable IntrinsicGasCost.
refine {|
  encode x := encode (IntrinsicGasCost_execution x, IntrinsicGasCost_state x, IntrinsicGasCost_calldata_floor x);
  decode x := '(x0, x1, x2) ← decode x;
              mret (Build_IntrinsicGasCost x0 x1 x2)
|}.
abstract (
  intros [x0 x1 x2];
  rewrite decode_encode;
  reflexivity).
Defined.

Notation "{[ r 'with' 'IntrinsicGasCost_execution' := e ]}" :=
  match r with Build_IntrinsicGasCost _ (_ as f1) (_ as f2) =>
    Build_IntrinsicGasCost e f1 f2 end (at level 1).
Notation "{[ r 'with' 'IntrinsicGasCost_state' := e ]}" :=
  match r with Build_IntrinsicGasCost (_ as f0) _ (_ as f2) =>
    Build_IntrinsicGasCost f0 e f2 end (at level 1).
Notation "{[ r 'with' 'IntrinsicGasCost_calldata_floor' := e ]}" :=
  match r with Build_IntrinsicGasCost (_ as f0) (_ as f1) _ =>
    Build_IntrinsicGasCost f0 f1 e end (at level 1).
